    secondary_home_phone varchar(20),
    mobile_phone varchar(20),
    business_phone varchar(20),
    business_phone_ext varchar(10),
    home_fax varchar(20),
    work_fax varchar(20),
    pager_number varchar(20),
    text_message_phone varchar(20),
    text_message_carrier varchar(30),
    email_address varchar(120),
