    name_control_code varchar(4),
    tax_code varchar(10),
    default_sale_type varchar(10),
    is_delete_data_flag boolean,
    delete_data_date date,
    delete_data_time varchar(8),
    opt_out_flag boolean,
    opt_out_date date,
    opt_out_time varchar(8),
    casl_consent_timestamp timestamptz,
    overdue_30_days numeric(13,2),
    overdue_60_days numeric(13,2),
    overdue_90_days numeric(13,2),
    overdue_120_days numeric(13,2),
    current_balance numeric(13,2),
    credit_limit numeric(13,2),
    current_due numeric(13,2),
